# DK KHM.  Kolding Syd - Hejlsminde
#
let kh = path("d3.dk.khm");

with detail = 3, railway = :first :pax :removed {
    with link = "point.dk.Kolding-Syd", railway = :station {
        let kos = path("d3.dk.kks.d3");

        track(kos[:kos, :kos.yv]);
        track(
                kos[:kos - 0.1dl, :kos]
            --  kos[:kos + 1dl, :kos.yv] >> 1ms >> 1mt
        );
        marker(:right :de.bf, kos[:kos + 0.5sw] >> 1ms >> 1.5mt);
        slabel(:left, kos[:kos + 0.5sw] >> 1ms >> 1.5mt >> 1sh + (-1sw, 1dt),
            span(:bold, "Kolding Syd")
        );
    }

    with link = "line.dk.KHM" {
        track(:ror, kh[:kos.yv - 0.1dl, :kos.yv + 1seg]);
        track(kh[:kos.yv + 0.9seg, :tvb - 0.49sw]);
    }

    with link = "point.dk.Tved-Byvej", railway = :station {
        track(kh[:tvb - 0.5sw, :tvb + 0.5sw]);
        marker(:right :de.hp, kh[:tvb] >> 0.5mt);
        slabel(:right, kh[:tvb] << 0.5mt + (1dt, 0.5dt), "Tved Byvej");
    }

    with link = "line.dk.KHM" {
        track(kh[:tvb + 0.49sw, :tve - 0.49sw]);
    }

    with link = "point.dk.Tved", railway = :station {
        track(kh[:tve - 0.5sw, :tve + 0.5sw]);
        marker(:right :de.hp, kh[:tve] >> 0.5mt);
        slabel(:right, kh[:tve] << 0.5mt + (1dt, 0.5dt),
            "Tved"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:tve + 0.49sw, :tve + 0.76km]);
        line_label(:right:ne, kh[:tve + 0.75km] >> 0.5mt, "KHM");
        track(kh[:tve + 0.74km, :str - 0.49sw]);
    }

    with link = "point.dk.Strårup", railway = :station {
        track(kh[:str - 0.5sw, :str + 0.5sw]);
        marker(:left :de.hp, kh[:str] << 0.5mt);
        slabel(:right, kh[:str] << 0.5mt << 1sh + (1.3dt, 0.8dt),
            "Strårup"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:str + 0.49sw, :skv - 0.49sw]);
    }

    with link = "point.dk.Skartved", railway = :station {
        track(kh[:skv - 0.5sw, :skv + 0.5sw]);
        marker(:right :de.hp, kh[:skv] >> 0.5mt);
        slabel(:left, kh[:skv] >> 0.5mt >> 1sh + (-1.4dt, 1.3dt),
            "Skartved"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:skv + 0.49sw, :bja - 0.49sw]);
    }

    with link = "point.dk.Bjært", railway = :station {
        track(kh[:bja - 0.5sw, :bja + 0.5sw]);
        marker(:left :de.bf, kh[:bja] << 0.5mt);
        slabel(:top, kh[:bja] << 0.5mt << 1sh + (0.3dt, -0.3dt),
            "Bjært"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:bja + 0.49sw, :aal - 0.49sw]);
    }

    with link = "point.dk.Aalry", railway = :station {
        track(kh[:aal - 0.5sw, :aal + 0.5sw]);
        marker(:left :de.hp, kh[:aal] << 0.5mt);
        slabel(:top, kh[:aal] << 0.5mt << 1sh + (0.3dt, -0.4dt),
            "Aalry"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:aal + 0.49sw, :var - 0.49sw]);
    }

    with link = "point.dk.Varmark", railway = :station {
        track(kh[:var - 0.5sw, :var + 0.5sw]);
        marker(:left :de.bf, kh[:var] << 0.5mt);
        slabel(:right, kh[:var] << 0.5mt << 1sh + (1.2dt, 0.8dt),
            "Varmark"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:var + 0.49sw, :vas - 0.49sw]);
    }

    with link = "point.dk.Varmark-Skov", railway = :station {
        track(kh[:vas - 0.5sw, :vas + 0.5sw]);
        marker(:left :de.hp, kh[:vas] << 0.5mt);
        slabel(:right, kh[:vas] << 0.5mt << 1sh + (1.2dt, 1.1dt),
