        );
    }

    with link = "line.dk.KHM" {
        track(kh[:vas + 0.49sw, :bjs - 0.49sw]);
    }

    with link = "point.dk.Bjært-Strand", railway = :station {
        track(kh[:bjs - 0.5sw, :bjs + 0.5sw]);
        marker(:left :de.hp, kh[:bjs] << 0.5mt);
        slabel(:bottom, kh[:bjs] << 0.5mt << 1sh + (4dt, 0.4dt),
            "Bjært Strand"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:bjs + 0.49sw, :dal - 0.49sw]);
    }

    with link = "point.dk.Dalager", railway = :station {
        track(kh[:dal - 0.5sw, :dal + 0.5sw]);
        marker(:right :de.bf, kh[:dal] >> 0.5mt);
        slabel(:left, kh[:dal] >> 0.5mt >> 1sh + (-1.2dt, 1dt),
            "Dalager"
