    with link = "line.dk.KHM" {
        track(kh[:dal + 0.49sw, :dal + 0.91km]);
        line_label(:right:e, kh[:dal + 0.9km] >> 0.5mt, (0dt, -0.2dt), "KHM");
        track(kh[:dal + 0.89km, :ska - 0.49sw]);
    }

    with link = "point.dk.Skamlingsbanke", railway = :station {
        track(kh[:ska - 0.5sw, :ska + 0.5sw]);
        marker(:left :de.hst, kh[:ska] << 0.5mt);
        slabel(:right, kh[:ska] << 0.5mt << 1sh + (1.2dt, 1.2dt),
            "Skamlingsbanke"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:ska + 0.49sw, :gro - 0.49sw]);
    }

    with link = "point.dk.Grønninghoved", railway = :station {
        track(kh[:gro - 0.5sw, :gro + 0.5sw]);
        marker(:right :de.hp, kh[:gro] >> 0.5mt);
        slabel(:left, kh[:gro] >> 0.5mt >> 1sh + (-1.5dt, 0dt),
            "Grønninghoved"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:gro + 0.49sw, :sjo - 0.49sw]);
    }

    with link = "point.dk.Sjølund", railway = :station {
        track(kh[:sjo - 0.5sw, :sjo + 0.5sw]);
        marker(:left :de.bf, kh[:sjo] << 0.5mt);
        slabel(:left, kh[:sjo] >> 0.5mt + (-1dt, 1dt),
            "Sjølund"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:sjo + 0.49sw, :vej - 0.49sw]);
    }

    with link = "point.dk.Vejstruprød", railway = :station {
        track(kh[:vej - 0.5sw, :vej + 0.5sw]);
        marker(:left :de.hp, kh[:vej] << 0.5mt);
        slabel(:right, kh[:vej] << 0.5mt << 1sh + (1dt, 1dt),
            "Vejstruprød"
        );
    }

    with link = "line.dk.KHM" {
        track(kh[:vej + 0.49sw, :kar - 0.49sw]);
