    }

    with link = "line.dk.KHM" {
        track(kh[:kar + 0.49sw, :hes - 0.49sw]);
    }

    with link = "point.dk.Hejls", railway = :station {
        track(kh[:hes - 0.5sw, :hes + 0.5sw]);
