    with link = "line.dk.KHM" {
        track(kh[:hes + 0.49sw, :hes + 1.21km]);
        line_label(:right:ne, kh[:hes + 1.2km] >> 0.5mt, "KHM");
        track(kh[:hes + 1.19km, :hem - 0.49sw]);
    }

    with link = "point.dk.Hejlsminde", railway = :station {
        track(kh[:hem - 0.5sw, :hem + 0.5sw]);
        marker(:left :de.bf, kh[:hem] << 0.5mt);
        slabel(:right :bold, kh[:hem] << 0.5mt << 1sh + (1.4dt, 1dt),
            "Hejlsminde"
        );
    }
}

